const crypto = require('crypto');

// Same scheme as convex/lib/hmac.ts:
//   X-LendLoop-Signature = hex(HMAC-SHA256(secret, `${timestamp}.${rawBody}`))
function sign(rawBody) {
  const secret = $env.LENDLOOP_HMAC_SECRET;
  if (!secret || secret.length < 32) {
    throw new Error('LENDLOOP_HMAC_SECRET is missing or shorter than 32 characters in the n8n container.');
  }
  const timestamp = String(Math.floor(Date.now() / 1000));
  const signature = crypto.createHmac('sha256', secret).update(`${timestamp}.${rawBody}`).digest('hex');
  return { timestamp, signature };
}

// n8n runs this workflow when the notification or reminder workflow fails.
// Convex stores the report (deduplicated by execution id) and admins see it
// on the Admin page, so failures do not stay hidden inside n8n.
const { execution = {}, workflow = {}, trigger } = $input.first().json;
const error = execution.error ?? trigger?.error ?? {};

const report = {
  workflowId: String(workflow.id ?? 'unknown'),
  workflowName: String(workflow.name ?? 'unknown'),
  // Trigger failures have no execution id; use a timestamp so each is kept.
  executionId: String(execution.id ?? `trigger-${Date.now()}`),
  failedNode: execution.lastNodeExecuted ?? error.node?.name,
  message: String(error.message ?? 'Unknown error').slice(0, 1000),
};

const rawBody = JSON.stringify(report);
return [{ json: { rawBody, ...sign(rawBody) } }];
